komponenten-dropdowns-combobox--interakt.snippet:
import { Component } from '@angular/core';
import { ComboboxComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [ComboboxComponent],
  template: `
    <cds-combobox
        [label]="'Thema'"
        [options]="[{value: 'ki', label: 'Angewandte KI'}, {value: 'es', label: 'Effektive Software'}, {value: 'wo', label: 'Wirksame Organisationen'}, {value: 'strategie', label: 'Strategie-Workshop'}, {value: 'daten', label: 'Datenanalyse & Reporting'}, {value: 'auto', label: 'Prozessautomatisierung'}, {value: 'cloud', label: 'Cloud-Migration'}, {value: 'change', label: 'Change-Begleitung'}, {value: 'training', label: 'Schulung & Training'}, {value: 'presse', label: 'Presse & Medien'}]"
        [placeholder]="'Thema suchen…'"
        [emptyText]="'Kein Thema gefunden'"
        [area]="'es'"
        [multi]="false"
        [disabled]="false"
        (disabledChange)="disabledChange($event)"
        (valueChange)="valueChange($event)"
        (valuesChange)="valuesChange($event)"
    />`,
})
export class DemoComponent {
  disabledChange(event: unknown) {}
  valueChange(event: unknown) {}
  valuesChange(event: unknown) {}
}

